void pendingPreservesRegistration(){Fixture f;f.begin();require(f.registered=="old-working-host"&&f.commits==0,"Pending request replaced a working registration");tickConnectionRequest(f.access);require(f.state->id==requestId&&f.sends==1,"Create response missing");tickConnectionRequest(f.access);f.now+=2999;tickConnectionRequest(f.access);require(f.sends==1,"Request polling exceeded three-second rate");f.now++;f.transport=[](const auto&,const auto&){return response("approved",false,true);};require(tickConnectionRequest(f.access),"Approved request did not apply");require(f.commits==1&&f.state->committed&&f.state->key.empty()&&f.state->approved.token.empty(),"Completed request retained proof or skipped registration");require(f.registered==hostId,"Approved registration was not selected");const auto publicState=publicConnectionRequest(f.state);require(publicState.find(key)==std::string::npos&&publicState.find(token)==std::string::npos&&publicState.find("requestKey")==std::string::npos&&publicState.find("hostToken")==std::string::npos,"Public state leaked a secret");}
void createApprovedNeedsStatus(){Fixture f;f.begin();f.transport=[](const auto&,const auto&){return response("approved",true,false);};tickConnectionRequest(f.access);require(f.state->status=="approved"&&!f.state->committed&&!f.commits,"Create acknowledgement was treated as credentials");require(JsonParser::parse(publicConnectionRequest(f.state)).get("status").string()=="pending","Uncommitted approval was labeled registered");f.advance();f.transport=[](const auto& path,const auto&){require(path==L"/api/v1/hosts/requests/status","Approved create did not recover through status");return response("approved",false,true);};require(tickConnectionRequest(f.access)&&f.commits==1,"Approval status could not complete registration");}
void lostCreateKeepsKey(){Fixture f;f.begin();f.transport=[](const auto&,const auto&)->Json{throw std::runtime_error("Fixture dropped create response");};tickConnectionRequest(f.access);require(f.state->id.empty()&&f.state->key==key,"Lost response replaced proof key");f.advance();f.transport=[](const auto&,const auto&){return response("pending",true);};tickConnectionRequest(f.access);require(f.bodies.size()==2&&f.bodies[0]==f.bodies[1],"Lost create was not retried idempotently");const auto savedVersion=f.state->version;beginConnectionRequest(f.access,L"https://broker.invalid","QA-WINDOWS",uuid,"99.99.99",std::string(43,'Z'));require(f.state->key==key&&f.state->version==savedVersion,"Pending upgrade changed request metadata/key");}
void failedCommitResumesSealedApproval(){Fixture f;f.begin();tickConnectionRequest(f.access);f.advance();f.transport=[](const auto&,const auto&){return response("approved",false,true);};f.failCommit=true;tickConnectionRequest(f.access);require(f.state->approved.token==token&&!f.state->committed&&f.registered=="old-working-host","Failed commit lost proof or previous registration");const int sends=f.sends;tickConnectionRequest(f.access);require(f.commits==1,"Failed commit ignored retry delay");f.advance();f.failCommit=false;require(tickConnectionRequest(f.access)&&f.sends==sends&&f.commits==2,"Restart-style recovery reissued rather than applying sealed approval");}
void terminalSaveFailureStillSignalsReload(){Fixture f;f.begin();tickConnectionRequest(f.access);f.advance();f.transport=[](const auto&,const auto&){return response("approved",false,true);};f.failTerminalSave=true;require(tickConnectionRequest(f.access)&&f.registered==hostId,"Completed credential write did not signal reload after acknowledgement-save failure");require(!f.state->committed&&f.state->approved.token==token,"Failed final marker discarded the recovery record");f.advance();f.failTerminalSave=false;require(tickConnectionRequest(f.access)&&f.state->committed,"Idempotent approval recovery failed");}
void lateApprovalAfterCancelIsDiscarded(){Fixture f;f.begin();tickConnectionRequest(f.access);f.advance();f.transport=[&](const auto&,const auto&){cancelConnectionRequest(f.access);return response("approved",false,true);};tickConnectionRequest(f.access);require(f.state->status=="cancelled"&&!f.commits&&f.registered=="old-working-host","Late approval overrode local cancellation");require(JsonParser::parse(publicConnectionRequest(f.state)).get("error").string()=="cancel_pending","Cancel acknowledgement wait was hidden");f.transport=[](const auto& path,const auto&){require(path==L"/api/v1/hosts/requests/cancel","Cancelled request did not reach cancellation route");return response("rejected");};tickConnectionRequest(f.access);require(f.state->cancelAcknowledged&&f.state->key.empty(),"Server cancellation did not retire proof key");}
void lateOldOriginCannotReplaceNewRequest(){Fixture f;f.begin();tickConnectionRequest(f.access);f.advance();f.transport=[&](const auto&,const auto&){cancelConnectionRequest(f.access);f.state->cancelAcknowledged=true;beginConnectionRequest(f.access,L"https://other.invalid","QA-WINDOWS",uuid,MULTITAP_HOST_VERSION_UTF8,std::string(43,'N'));return response("approved",false,true);};tickConnectionRequest(f.access);require(f.state->origin==L"https://other.invalid"&&f.state->key==std::string(43,'N')&&f.commits==0,"Old-origin response replaced newer request");}
void cancellationRecoversUnknownId(){Fixture f;f.begin();cancelConnectionRequest(f.access);tickConnectionRequest(f.access);require(f.state->status=="cancelled"&&f.state->id==requestId&&!f.state->cancelAcknowledged,"Cancelled lost-create request could not recover its ID");f.advance();f.transport=[](const auto& path,const auto&){require(path==L"/api/v1/hosts/requests/cancel","Recovered ID did not cancel");return response("rejected");};tickConnectionRequest(f.access);require(f.state->cancelAcknowledged,"Recovered cancellation was not acknowledged");}
void approvedCancellationContinuesRegistration(){Fixture f;f.begin();tickConnectionRequest(f.access);cancelConnectionRequest(f.access);f.transport=[](const auto&,const auto&)->Json{throw BrokerHttpError(409,"host_request_already_approved");};tickConnectionRequest(f.access);require(f.state->status=="pending"&&f.state->error=="already_approved"&&f.state->key==key&&!f.commits,"Approved cancel conflict lost recoverable proof");f.advance();f.transport=[](const auto&,const auto&){return response("approved",false,true);};require(tickConnectionRequest(f.access)&&f.state->committed,"Issued approval was not recovered after cancellation conflict");}
void invalidApprovalDoesNotCommit(){Fixture f;f.begin();tickConnectionRequest(f.access);f.advance();f.transport=[](const auto&,const auto&){auto value=response("approved",false,true);std::get<Json::Object>(std::get<Json::Object>(value.value)["credentials"].value)["hostToken"].value=std::string("invalid");return value;};tickConnectionRequest(f.access);require(f.commits==0&&f.registered=="old-working-host"&&f.state->error=="invalid_response","Invalid approved credential reached storage");}
void expiredRejectedAndWrongMachineStop(){for(const auto* state:{"expired","rejected"}){Fixture f;f.begin();f.transport=[&](const auto&,const auto&){return response(state,true);};tickConnectionRequest(f.access);f.advance();tickConnectionRequest(f.access);require(f.sends==1&&!f.state->active()&&f.state->key.empty(),"Terminal request kept polling or retained proof");}Fixture f;f.begin();f.access.machineIdentity=[] {return std::string(hostId);};tickConnectionRequest(f.access);require(f.sends==0&&f.state->status=="rejected"&&f.state->error=="machine_identity_changed","Cloned/mismatched VM request reached server");}
void actualDesktopIdContract(){require(!connectionUuid(desktopId)&&connectionDesktopId(desktopId),"Real pve-149 desktop ID rejected or mistaken for UUID");require(connectionDesktopId("A")&&connectionDesktopId(std::string(80,'z'))&&connectionDesktopId("pve_149"),"Valid server desktop ID rejected");for(const auto& value:{std::string(),std::string("../pve-149"),std::string("_pve-149"),std::string("pve.149"),std::string(81,'a'),std::string("한글")})require(!connectionDesktopId(value),"Invalid server desktop ID accepted");}
void networkLeaseAndReplacementGuards(){Fixture f;f.begin();auto network=f.access.networkLock(0);require(!tickConnectionRequest(f.access)&&!f.sends,"Concurrent network owner was ignored");network.reset();tickConnectionRequest(f.access);bool rejected=false;try{beginConnectionRequest(f.access,L"https://other.invalid","QA-WINDOWS",uuid,MULTITAP_HOST_VERSION_UTF8,std::string(43,'N'));}catch(...){rejected=true;}require(rejected&&f.state->key==key,"Active request was silently replaced");cancelConnectionRequest(f.access);rejected=false;try{f.begin();}catch(...){rejected=true;}require(rejected,"Unacknowledged cancellation allowed a conflicting new key");}
void parsingAndEntropy(){require(connectionExpiry("2024-02-29T12:34:56.123Z")>0,"Valid leap-day expiry rejected");for(const auto* value:{"2023-02-29T00:00:00.000Z","2026-10-23T24:00:00.000Z","2026-10-23T00:00:00+00:00","2026-10-23T00:00:00.00Z"}){bool failed=false;try{connectionExpiry(value);}catch(...){failed=true;}require(failed,"Malformed expiry accepted");}const auto a=connectionRequestKey(),b=connectionRequestKey(),c=connectionRequestKey();require(validToken(a)&&validToken(b)&&validToken(c)&&a!=b&&b!=c&&a!=c,"OS random proof key generation failed");}
void actualMachineDpapiDummy(){std::string text="Multitap-pending-QA-dummy-no-real-credential";DATA_BLOB source{DWORD(text.size()),reinterpret_cast<BYTE*>(text.data())},sealed{},plain{};winCheck(CryptProtectData(&source,L"Multitap request QA dummy",nullptr,nullptr,nullptr,CRYPTPROTECT_LOCAL_MACHINE|CRYPTPROTECT_UI_FORBIDDEN,&sealed),"Dummy request encryption");DATA_BLOB encrypted{sealed.cbData,sealed.pbData};winCheck(CryptUnprotectData(&encrypted,nullptr,nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&plain),"Dummy request decryption");const bool matched=plain.cbData==text.size()&&std::memcmp(plain.pbData,text.data(),text.size())==0;SecureZeroMemory(plain.pbData,plain.cbData);LocalFree(plain.pbData);LocalFree(sealed.pbData);require(matched,"Actual machine DPAPI dummy roundtrip failed");}
void aclPolicy(){for(const auto* sddl:{L"D:P(A;;FA;;;SY)(A;;FA;;;BA)",L"D:P(A;;FA;;;SY)(A;;FA;;;BA)(A;;FR;;;BU)",L"D:P(A;;FA;;;SY)(A;;FA;;;BA)(A;;FW;;;BU)"}){PSECURITY_DESCRIPTOR descriptor=nullptr;winCheck(ConvertStringSecurityDescriptorToSecurityDescriptorW(sddl,SDDL_REVISION_1,&descriptor,nullptr),"QA private ACL descriptor");PACL dacl=nullptr;BOOL present=FALSE,defaulted=FALSE;winCheck(GetSecurityDescriptorDacl(descriptor,&present,&dacl,&defaulted),"QA private ACL read");const bool safe=privateConnectionAcl(dacl);LocalFree(descriptor);require(safe==(std::wstring(sddl)==L"D:P(A;;FA;;;SY)(A;;FA;;;BA)"),"Public read/write ACL accepted for machine-DPAPI request");}}
