void verificationCodeMatchesBroker(){
  require(connectionVerificationCode(key)=="49J2-HQP1","Request code differs from the broker derivation");
  require(connectionVerificationCode(std::string(43,'N'))!=connectionVerificationCode(key),"Different request keys produced one code");
  require(std::wstring(connectionRequestHeaders).find(L"\r\nX-Multitap-Host-Request-Code: v1\r\n")!=std::wstring::npos,"Requests do not declare that the Host shows the code");
  Fixture f;f.begin();require(JsonParser::parse(publicConnectionRequest(f.state)).get("verificationCode").string()=="49J2-HQP1","A request awaiting approval does not show its code");
  tickConnectionRequest(f.access);const auto shown=publicConnectionRequest(f.state);require(JsonParser::parse(shown).get("verificationCode").string()=="49J2-HQP1"&&shown.find(key)==std::string::npos,"Pending code missing or the key leaked");
  f.advance();f.transport=[](const auto&,const auto&){return response("approved",false,true);};tickConnectionRequest(f.access);
  require(std::holds_alternative<std::nullptr_t>(JsonParser::parse(publicConnectionRequest(f.state)).get("verificationCode").value),"A completed registration still shows a code");
  Fixture rejected;rejected.begin();rejected.transport=[](const auto&,const auto&){return response("rejected",true);};tickConnectionRequest(rejected.access);
  require(std::holds_alternative<std::nullptr_t>(JsonParser::parse(publicConnectionRequest(rejected.state)).get("verificationCode").value),"A rejected request still shows a code");
}
bool actualKernelMutex(){if(!elevated())return false;const auto name=L"Global\\MultitapHost.QA.Pending."+randomName();auto owner=nativeConnectionLock(name.c_str(),0);require(bool(owner),"Owned QA kernel mutex could not be acquired");bool excluded=false;std::thread contender([&]{try{excluded=!nativeConnectionLock(name.c_str(),0);}catch(...){}});contender.join();require(excluded,"Second thread entered the same pending network mutex");owner.reset();bool released=false;std::thread successor([&]{try{released=bool(nativeConnectionLock(name.c_str(),100));}catch(...){}});successor.join();require(released,"QA kernel mutex did not release");return true;}
int targetedCancellation(){
  int passed=0;
  {Fixture f;f.begin();const auto shown=JsonParser::parse(publicConnectionRequest(f.state));
    const auto revision=shown.get("cancelRevision").string();
    require(shown.get("cancelProtocol").string()=="cancel-request-v1"&&revision.size()==64,"Exact cancellation protocol/identity unavailable");
    require(publicConnectionRequest(f.state).find(key)==std::string::npos,"Cancellation identity leaked its protected key");
    // Preserve the lost-create recovery path: no broker ID exists at consent.
    require(f.state->id.empty(),"Unknown-ID fixture unexpectedly had an ID");
    cancelConnectionRequestV1(f.access,revision);tickConnectionRequest(f.access);
    require(f.state->status=="cancelled"&&f.state->id==requestId&&!f.state->cancelAcknowledged,"Targeted unknown-ID cancellation lost recovery");++passed;}
  {Fixture f;f.begin();const auto revision=connectionCancellationRevision(*f.state);
    tickConnectionRequest(f.access);
    require(!f.state->id.empty()&&connectionCancellationRevision(*f.state)==revision,"Broker ID/expiry refresh changed the SAME request identity");
    cancelConnectionRequestV1(f.access,revision);require(f.state->status=="cancelled","Same request could not be cancelled after ID recovery");++passed;}
  {Fixture f;f.begin();const auto revision=connectionCancellationRevision(*f.state);
    // Replace while taking the native lock, after any possible caller precheck.
    const auto acquire=f.access.stateLock;
    f.access.stateLock=[&](DWORD timeout){auto lock=acquire(timeout);if(lock){f.state->key=std::string(43,'N');++f.state->createdAt;}return lock;};
    bool refused=false;try{cancelConnectionRequestV1(f.access,revision);}catch(...){refused=true;}
    require(refused&&f.state->status=="pending"&&f.state->key==std::string(43,'N')&&f.sends==0&&f.commits==0,"Earlier consent cancelled a successor under the state lock");++passed;}
  {Fixture f;f.begin();const auto revision=connectionCancellationRevision(*f.state);
    f.state->committed=true;f.state->status="approved";bool refused=false;
    try{cancelConnectionRequestV1(f.access,revision);}catch(...){refused=true;}
    require(refused&&f.state->committed&&f.state->status=="approved"&&f.registered=="old-working-host","Targeted cancellation changed a completed registration");++passed;}
  {Fixture f;f.begin();for(const auto& revision:{std::string(),std::string(63,'a'),std::string(64,'A'),std::string(64,'0')}){
      bool refused=false;try{cancelConnectionRequestV1(f.access,revision);}catch(...){refused=true;}
      require(refused&&f.state->status=="pending"&&!f.sends&&!f.commits,"Invalid/stale cancellation identity mutated the pending request");
    }++passed;}
  {Fixture f;f.begin();const auto revision=connectionCancellationRevision(*f.state);f.state.reset();bool refused=false;
    try{cancelConnectionRequestV1(f.access,revision);}catch(...){refused=true;}
    require(refused&&!f.state&&!f.sends&&!f.commits,"Absent target cancellation acted on another state");++passed;}
  return passed;
}
